export async function bootstrapPartnerSession(auth, location, history) {
  const url = new URL(location.href);
  const loginToken = url.searchParams.get('login_token');
  if (!loginToken) return;
  url.searchParams.delete('login_token');
  history.replaceState(null, '', url.href);
  await auth.exchange(loginToken);
}
export async function partnerCallback(auth, router) {
  const { login_token: loginToken, ...rest } = router.query;
  await router.replace({ pathname: router.pathname, query: rest });
  await auth.exchange(loginToken);
}
export async function embeddedPartnerLogin(auth, location, history) {
  const url = new URL(location.href);
  const loginToken = url.searchParams.get('login_token');
  url.searchParams.delete('login_token');
  history.replaceState(null, '', url.href);
  await auth.exchange(loginToken);
}

